        show("child after writes:");
        printf("child sees buf[0]=%d, sum=%ld\n", buf[0], sum);
        _exit(0);
    }
    waitpid(pid, NULL, 0);
    printf("parent sees buf[0]=%d (unchanged)\n", buf[0]);
    return 0;
