static volatile sig_atomic_t got_term = 0, got_int = 0, got_chld = 0;

static void on_signal(int sig) {
    if (sig == SIGTERM) got_term = 1;
    else if (sig == SIGINT) got_int = 1;
    else if (sig == SIGCHLD) got_chld = 1;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof sa);
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGTERM, &sa, NULL);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGCHLD, &sa, NULL);
    /* SIGKILL and SIGSTOP cannot be caught: sigaction fails with EINVAL */
    if (sigaction(SIGKILL, &sa, NULL) == -1) perror("sigaction(SIGKILL)");

    printf("pid=%d waiting for signals\n", getpid());
    fflush(stdout);
    if (fork() == 0) { usleep(300000); _exit(0); }   /* produces SIGCHLD */
    while (!got_term) pause();
    if (got_chld) {
        int st; pid_t p = waitpid(-1, &st, WNOHANG);
        printf("SIGCHLD seen, reaped %d\n", p);
    }
    if (got_int) printf("SIGINT seen\n");
    printf("SIGTERM seen: cleaning up and exiting with status 0\n");
    return 0;
}

