/* Classic double-fork daemonization. Sleeps 20 s so that ps can inspect it. */
int main(void) {
    if (fork() > 0) exit(0);          /* 1st fork: parent returns to the shell */
    setsid();                         /* new session, no controlling terminal */
    if (fork() > 0) exit(0);          /* 2nd fork: the daemon is not a session leader */
    chdir("/");
    umask(022);
    int fd = open("/dev/null", O_RDWR);
    dup2(fd, 0); dup2(fd, 1); dup2(fd, 2);
    sleep(20);
    return 0;
}

