int main(void) {
    int fd[2];
    if (pipe(fd) == -1) { perror("pipe"); return 1; }
    printf("pipe: read end fd=%d, write end fd=%d\n", fd[0], fd[1]);
    pid_t pid = fork();
    if (pid == 0) {
        close(fd[0]);                                   /* child writes */
        const char *msg = "hello through the kernel pipe buffer";
        write(fd[1], msg, strlen(msg));
        close(fd[1]);
        _exit(0);
    }
    close(fd[1]);                                       /* parent reads */
    char buf[64];
    ssize_t n = read(fd[0], buf, sizeof buf - 1);
    buf[n] = '\0';
    printf("parent read %zd bytes: %s\n", n, buf);
    n = read(fd[0], buf, sizeof buf);                   /* all writers closed */
    printf("second read returns %zd (end of file)\n", n);
    waitpid(pid, NULL, 0);
    return 0;
}

