                    + new String(req.array(), 0, req.position(), StandardCharsets.UTF_8));
                conn.write(ByteBuffer.wrap("200 OK".getBytes(StandardCharsets.UTF_8)));
            }
            client.join();
        }
        Files.deleteIfExists(path);
    }
