import java.io.InputStream;
import java.util.concurrent.TimeUnit;

public class PipeHang {
    public static void main(String[] args) throws Exception {
        boolean drain = args.length > 0 && args[0].equals("drain");
        // The child prints about 600 KB, far more than the 64 KiB pipe buffer.
        Process p = new ProcessBuilder("/usr/bin/seq", "1", "100000").start();
        System.out.println("child pid " + p.pid() + ", drain=" + drain);
        long bytes = 0;
        if (drain) {
            try (InputStream in = p.getInputStream()) {
                bytes = in.transferTo(java.io.OutputStream.nullOutputStream());
            }
        }
        boolean done = p.waitFor(5, TimeUnit.SECONDS);
        System.out.println("finished=" + done + ", bytes read=" + bytes);
        if (!done) p.destroyForcibly();
    }
}

