public class ThreadMap {
    static int nativeThreads() throws Exception {
        try (var s = Files.list(Path.of("/proc/self/task"))) { return (int) s.count(); }
    }

    public static void main(String[] args) throws Exception {
        System.out.println("pid " + ProcessHandle.current().pid()
            + ", native threads at start: " + nativeThreads());
        CountDownLatch release = new CountDownLatch(1);
        for (int i = 0; i < 5; i++) {
            Thread.ofPlatform().name("worker-" + i).start(() -> {
                try { release.await(); } catch (InterruptedException e) { }
            });
        }
        System.out.println("after 5 platform threads    : " + nativeThreads());
        try (var exec = Executors.newVirtualThreadPerTaskExecutor()) {
            IntStream.range(0, 10_000).forEach(i -> exec.submit(() -> {
                try { release.await(); } catch (InterruptedException e) { }
                return i;
            }));
            Thread.sleep(500);
            System.out.println("after 10000 virtual threads : " + nativeThreads());
            try (var s = Files.list(Path.of("/proc/self/task"))) {
                s.map(p -> { try { return Files.readString(p.resolve("comm")).trim(); }
                             catch (Exception e) { return "?"; } })
                 .sorted().forEach(n -> System.out.print(n + "  "));
            }
            System.out.println();
            release.countDown();
        }
    }
}

