import java.util.concurrent.ConcurrentLinkedQueue;

public class HotThread {
    static final ConcurrentLinkedQueue<String> jobs = new ConcurrentLinkedQueue<>();

    public static void main(String[] args) throws Exception {
        Thread idle = new Thread(() -> {
            try { Thread.sleep(600_000); } catch (InterruptedException e) { }
        }, "http-nio-8080-exec-1");
        idle.start();
        Thread hot = new Thread(HotThread::consume, "order-consumer");
        hot.start();
        hot.join();
    }

    // Bug: a busy-wait consumer. poll() returns null immediately when the queue is empty,
    // so the loop never blocks and one core is fully used.
    static void consume() {
        long handled = 0;
        while (true) {
            String job = jobs.poll();
            if (job != null) {
                handled++;
            }
        }
    }
}

#define _GNU_SOURCE
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <unistd.h>

#define THREADS 2
#define ROUNDS 20
#define WORK_MS 40

static double wall_ms(void) {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec * 1e3 + ts.tv_nsec / 1e6;
}
static double cpu_ms(void) {
    struct timespec ts; clock_gettime(CLOCK_THREAD_CPUTIME_ID, &ts);
    return ts.tv_sec * 1e3 + ts.tv_nsec / 1e6;
}
static double lat[ROUNDS][THREADS];
static pthread_barrier_t barrier;

static void *worker(void *arg) {
    int id = (int)(long)arg;
    for (int r = 0; r < ROUNDS; r++) {
        pthread_barrier_wait(&barrier);            /* all "requests" arrive together */
        double w0 = wall_ms(), c0 = cpu_ms();
        while (cpu_ms() - c0 < WORK_MS) { }        /* WORK_MS of pure CPU work */
        lat[r][id] = wall_ms() - w0;
        pthread_barrier_wait(&barrier);
        if (id == 0) usleep(200000);               /* idle gap between bursts */
    }
    return NULL;
}
static int cmp(const void *a, const void *b) {
    double x = *(double *)a, y = *(double *)b;
    return (x > y) - (x < y);
}

int main(void) {
    pthread_t t[THREADS];
    pthread_barrier_init(&barrier, NULL, THREADS);
    for (long i = 0; i < THREADS; i++) pthread_create(&t[i], NULL, worker, (void *)i);
    for (int i = 0; i < THREADS; i++) pthread_join(t[i], NULL);
    double all[ROUNDS * THREADS]; int n = 0;
    for (int r = 0; r < ROUNDS; r++) for (int i = 0; i < THREADS; i++) all[n++] = lat[r][i];
    qsort(all, n, sizeof(double), cmp);
    printf("requests=%d  work=%d ms CPU each  latency ms: p50=%.0f p90=%.0f max=%.0f\n",
           n, WORK_MS, all[n / 2], all[n * 9 / 10], all[n - 1]);
    return 0;
}
